def detect_drift(desired, real):
    drift = {}
    for name, attrs in desired.items():
        real_attrs = real.get(name, {})
        diffs = {k: (v, real_attrs.get(k)) for k, v in attrs.items() if real_attrs.get(k) != v}
        if diffs:
            drift[name] = diffs
    return drift


desired_state = {"aws_instance.web": {"instance_type": "t2.micro"}}
real_state = {"aws_instance.web": {"instance_type": "t2.large"}}

drift = detect_drift(desired_state, real_state)
for resource, diffs in drift.items():
    for attr, (expected, actual) in diffs.items():
        print(f"{resource}.{attr}: expected {expected}, found {actual}")
